function validState(s){return s&&['jobs','contacts','events','drafts','tasks','notes'].every(k=>Array.isArray(s[k]))&&(!s.weeklySummaries||Array.isArray(s.weeklySummaries)&&s.weeklySummaries.every(x=>{try{C.validateWeeklySummary(x);return true;}catch{return false;}}))&&s.contacts.every(c=>typeof c.name==='string'&&Array.isArray(c.tags))&&s.events.every(ev=>{try{C.validateEvent(ev);return true;}catch{return false;}});}
